def process(rainfall_combined):
    df = rainfall_combined.copy()
    df['Year'] = pd.to_numeric(df['Year'], errors='coerce')

    months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
    month_nums = list(range(1, 13))

    rows = []
    for year in df['Year'].dropna().unique():
        year_data = df[df['Year'] == year].iloc[0]
        for month_name, month_num in zip(months, month_nums):
            val = year_data[month_name]
            if pd.isna(val) or val == 'M':
                val_numeric = None
            else:
                try:
                    val_numeric = float(val)
                except:
                    val_numeric = None
            rows.append({'Year': int(year), 'Month': month_num, 'Rainfall': val_numeric})

    result = pd.DataFrame(rows)
    return result
